style.css:
@-moz-document regexp(".*") {
/* Targets the primary iframe wrapper and shadow-root hosts used by Mellowtel */
    div[class*="mellowtel"], 
    iframe[src*="mellowtel"],
    [id*="mellowtel"],
    .mellowtel-banner,
    .mellowtel-consent-container {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
        height: 0px !important;
        width: 0px !important;
    }
}
